package com.bank.dsa;

import java.math.BigInteger;
import java.util.logging.*;

// Runnable demo: product-loop pattern via factorial (foundation for compounding).
public class ProductLoopDemo {
    private static final Logger log = Logger.getLogger(ProductLoopDemo.class.getName());

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        Logger root = Logger.getLogger("");
        for (Handler old : root.getHandlers()) root.removeHandler(old);
        root.addHandler(h);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        ProductLoop loop = new ProductLoop();

        int n = 4;
        log.info(() -> n + "! via product loop = " + loop.factorial(n));
        log.info(() -> "0! (loop never runs) = " + loop.factorial(0));
    }
}

