class ProductLoop {
    // product = 1 (identity for ×); for i = 1..N { product *= i }.
    BigInteger factorial(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("N must be non-negative: " + n);
        }
        BigInteger product = BigInteger.ONE;   // seed = multiplicative identity (NOT zero!)
        int i = 1;                             // counter
        while (i <= n) {                       // loop while i <= N
            product = product.multiply(BigInteger.valueOf(i));
            i = i + 1;
        }
        return product;                        // N == 0 -> loop skipped -> product stays 1
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
